function fields(k,d={}){
 const f=(name,label,type='text',options=null,required=true,value='')=>({name,label,type,options,required,value:d[name]??value});
 const refs=kind=>items(kind).filter(i=>!i.data.archived).map(i=>opt(i.id,i.data.title+(kind==='module'?' · Year '+i.data.year:'')));
 const mods=refs('module').filter(m=>state.role!=='lecturer'||item(m.value).data.teacher===state.userId);
 const people=active().map(s=>opt(s.id,full(s)+' · Year '+s.year));
 const teachers=state.staff.map(s=>opt(s.id,s.name)),studentField=f('student','Student','select',people,true,state.studentId||selected);
 const body=f('body','Details / feedback','textarea',null,false),titleField=f('title','Title'),published=f('published','Publish to students','checkbox',null,false,true);
 const module=f('module','Class / module','select',mods);
 const names={
  programme:[titleField,f('years','Programme length (years)','number',null,true,3),f('annualCredits','Annual credit limit','number',null,true,120),f('qualification','Qualification',null,null,false,'BSc'),body],
  room:[titleField,f('building','Building / campus'),f('capacity','Capacity','number',null,true,30),body],
  module:[titleField,...(uni?[f('programme','Degree programme','select',refs('programme'))]:[f('subject','Subject name'),f('group','Subject group','select',[opt('option','Option'),opt('core','Core')],true,'option')]),f('year','Year','number',null,true,1),f('teacher','Lecturer / class teacher','select',teachers,false),f('capacity','Maximum class size','number',null,true,24),f('credits','Credits','number',null,true,uni?20:0),f('qualification','Qualification','text',null,false,uni?'Degree module':'A level'),...(uni?[f('compulsory','Compulsory module','checkbox',null,false,false),f('prerequisites','Prerequisite modules','multiple',refs('module').filter(m=>m.value!==d.id),false,[])]:[]),body],
  session:[titleField,module,f('room','Room','select',refs('room')),f('teacher','Lecturer / teacher','select',teachers),f('date','Date','date',null,true,date()),f('start','Start time','time',null,true,'09:00'),f('end','End time','time',null,true,'10:00'),f('type','Session type','select',['Lecture','Seminar','Lab','Workshop','Tutorial','Exam','AM registration','PM registration'].map(v=>opt(v,v)),true,'Lecture'),f('cancelled','Cancel this session','checkbox',null,false,false)],
  assessment:[titleField,module,body,f('due','Submission deadline','datetime-local',null,true,plus(date(),7)+'T16:00'),f('weight','Weighting within module (%)','number',null,true,100),f('passMark','Pass mark (%)','number',null,true,40),published],
  resource:[titleField,module,body,published,f('file','Attach PDF, Office document, image, text or ZIP (max 1 MB)','file',null,false)],
  notice:[titleField,body,f('year','Year audience (blank = everyone)','number',null,false,''),f('module','Module audience (optional)','select',refs('module'),false),published],
  appointment:[titleField,studentField,f('staff','Assigned member of staff','select',teachers,true,state.userId),f('date','Date','date',null,true,date()),f('time','Time','time',null,true,'10:00'),f('status','Status','select',['Booked','Completed','Cancelled'].map(v=>opt(v,v)),true,'Booked'),body,f('privateNote','Private staff note','textarea',null,false)],
  project:[titleField,studentField,f('staff','Supervisor','select',teachers,true,state.userId),f('deadline','Final deadline','date',null,true,plus(date(),90)),f('status','Stage','select',['Proposal','Approved','In progress','Draft review','Submitted','Completed'].map(v=>opt(v,v)),true,'Proposal'),body,f('milestones','Milestones and meeting record','textarea',null,false)],
  request:[titleField,...(!isStudent()?[studentField,f('staff','Assigned staff member','select',teachers,false,state.userId)]:[]),f('type','Request type','select',['Extension','Study adjustment','Support','Absence','Study break','Transfer'].map(v=>opt(v,v)),true,'Support'),f('assessment','Related assessment','select',refs('assessment'),false),body,f('requestedDate','Requested date','date',null,false),...(!isStudent()?[f('status','Decision / status','select',['Pending','Approved','Declined','Closed'].map(v=>opt(v,v)),true,'Pending'),f('approvedDate','Approved extension until','date',null,false),f('privateNote','Private staff note','textarea',null,false)]:[])],
  decision:[titleField,studentField,f('module','Related module (optional for awards)','select',refs('module'),false),f('outcome','Approved outcome','select',['Passed','Resit','Repeat','Progress','Award','Withdrawn'].map(v=>opt(v,v)),true,'Passed'),f('date','Decision date','date',null,true,date()),body],
  result:[titleField,studentField,f('assessment','Assessment','select',refs('assessment')),f('attempt','Attempt number','number',null,true,1),f('mark','Mark (%)','number',null,true,0),body,...(can('results')?[f('released','Approve and release to the student','checkbox',null,false,false)]:[])],
  submission:[titleField,body,f('file','Work attachment (max 1 MB)','file',null,false)]
 };return names[k]||[];
}
function fieldHTML(f){
 const val=f.value??'',attrs='name="'+f.name+'" '+(f.required?'required':'');
 let control;
 if(f.type==='select')control='<select '+attrs+'><option value="">Select…</option>'+f.options.map(o=>'<option value="'+esc(o.value)+'" '+(String(val)===String(o.value)?'selected':'')+'>'+esc(o.label)+'</option>').join('')+'</select>';
 else if(f.type==='multiple')control='<select '+attrs+' multiple size="5">'+f.options.map(o=>'<option value="'+o.value+'" '+(val.includes(o.value)?'selected':'')+'>'+esc(o.label)+'</option>').join('')+'</select>';
 else if(f.type==='textarea')control='<textarea '+attrs+' maxlength="10000">'+esc(val)+'</textarea>';
 else if(f.type==='checkbox')return '<label class="check"><input type="checkbox" name="'+f.name+'" '+(val?'checked':'')+'>'+esc(f.label)+'</label>';
 else if(f.type==='file')control='<input type="file" name="file" accept=".pdf,.docx,.pptx,.xlsx,.csv,.txt,.png,.jpg,.jpeg,.zip">';
 else {let v=val;if(f.type==='datetime-local'&&String(v).includes('Z')){const dt=new Date(v);v=new Date(dt-dt.getTimezoneOffset()*60000).toISOString().slice(0,16)}
 control='<input type="'+(f.type||'text')+'" '+attrs+' value="'+esc(v)+'" '+(f.type==='number'?'step="any"':'')+'>'}
 return '<label class="'+(['textarea','multiple','file'].includes(f.type)?'wide':'')+'">'+esc(f.label)+control+'</label>';
}
function modal(title,body){dlg.innerHTML='<div class="dialoghead"><h2>'+esc(title)+'</h2>'+btn('×','id="close-dialog" aria-label="Close dialog"','close')+'</div>'+body;by('close-dialog').onclick=()=>dlg.close();if(!dlg.open)dlg.showModal()}
async function fileData(f){if(!f?.size)return null;if(f.size>1048576)throw Error('Choose a file up to 1 MB.');if(!/\.(pdf|docx|pptx|xlsx|csv|txt|png|jpe?g|zip)$/i.test(f.name))throw Error('Unsupported file type.');const content=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=()=>reject(Error('Could not read file.'));r.readAsDataURL(f)});return {name:f.name,content}}
function edit(k,id=null,defaults={}){
 const record=item(id),d={...defaults,...record?.data};const ff=fields(k,d);
 modal((id?'Edit ':'New ')+(labels[k]||k).toLowerCase(),'<form id="entity-form"><div class="formgrid">'+ff.map(fieldHTML).join('')+'</div><div class="formactions"><button type="submit">'+(k==='submission'?'Submit final work':'Save record')+'</button></div><p id="form-error" class="error"></p>'+(k==='submission'?'<p class="muted spaced">Submission is final. Late work is accepted and labelled late. Resits and corrections are managed by staff.</p>':'')+'</form>');
 by('entity-form').onsubmit=e=>{e.preventDefault();act(async()=>{const fd=new FormData(e.target),data={...d};for(const f of ff){if(f.type==='file')continue;const v=fd.get(f.name);data[f.name]=f.type==='checkbox'?fd.has(f.name):f.type==='multiple'?fd.getAll(f.name):f.type==='number'?(v===''?null:Number(v)):f.type==='datetime-local'?(v?new Date(v).toISOString():null):v||null}
 if(k==='result'&&!can('results'))data.released=false;
 const payload={kind:k,data,id:record?.id,revision:record?.revision,file:await fileData(fd.get('file'))};
 await mutate('save',payload)})};
}
function editStudent(s=null){
 const f=(name,label,type='text',opts=null,value='')=>({name,label,type,options:opts,required:['first','last','year'].includes(name),value:s?.[name]??value});
 const ff=[f('first','First name'),f('last','Last name'),f('email','Email','email'),f('year','Year','number',null,1),f('programme_id','Programme','select',items('programme').map(p=>opt(p.id,p.data.title))),f('notes','Entry qualifications / placement notes','textarea'),f('archived','Archive student and revoke portal access','checkbox',null,false)];
 modal(s?'Edit student':'Add student','<form id="student-form"><div class="formgrid">'+ff.map(fieldHTML).join('')+'</div><div class="formactions"><button type="submit">Save student</button></div><p id="form-error" class="error"></p></form>');
 by('student-form').onsubmit=e=>{e.preventDefault();act(async()=>{const fd=new FormData(e.target),d=Object.fromEntries(fd);d.year=Number(d.year);d.archived=fd.has('archived');if(s){d.id=s.id;d.revision=s.revision}await mutate('student',d)})};
}
