  by('import-file').onchange=e=>act(async()=>{const f=e.target.files[0];if(f){if(f.size>1000000)throw Error('Use a file below 1 MB.');by('names').value=await f.text()}});
  const parse=()=>{const students=parseImport(by('names').value,by('order').value,by('import-year').value,by('import-programme').value);if(!students.length||students.length>500)throw Error('Import 1–500 students.');return students};
